import java.util.Scanner

fun main() {
    val br = System.`in`.bufferedReader()
    val (a, ta) = br.readLine().trim().split(" ").map { it.toInt() }
    val (b, tb) = br.readLine().trim().split(" ").map { it.toInt() }
    val parts = br.readLine().trim().split(":")
    val t = parts[0].toInt() * 60 + parts[1].toInt()
    var count = 0
    var s = 300
    while (s <= 1439) {
        if (s < t + ta && s + tb > t) count++
        s += b
    }
    println(count)
